def vehicle_picker():
 # Matched side profiles with distinct class proportions and open wheel arches.
 shapes=[
 '<path class="car-body" d="M15 37V27q0-3 3-4l6-2 9-12q2-3 6-3h20q6 0 10 5l10 13 7 2q4 1 4 5v6h-8a9 9 0 0 0-18 0H42a9 9 0 0 0-18 0z"/><path class="car-glass" d="m30 22 8-11h10v11zm23-11h7q3 0 5 3l6 8H53z"/><path d="M49 25v8m8-7h4M17 28h6m60 1h5M44 33h17"/>',
 '<path class="car-body" d="M8 37v-8q0-3 4-4l12-3L37 10q3-3 8-3h20q5 0 9 4l11 11 17 4q3 1 3 4v7h-9a9 9 0 0 0-18 0H37a9 9 0 0 0-18 0z"/><path class="car-glass" d="m31 22 11-10h12v10zm28-10h6q3 0 6 3l7 7H59z"/><path d="M55 25v9m8-8h5M11 29h9m76 0h7M40 33h35"/>',
 '<path class="car-body" d="M4 37v-8q0-3 4-4l14-3L36 11q4-3 9-3h22q7 0 12 4l13 10 15 3q4 1 4 5v7h-9a9 9 0 0 0-18 0H34a9 9 0 0 0-18 0z"/><path class="car-glass" d="m29 22 12-9h15v9zm32-9h7q4 0 8 3l8 6H61z"/><path d="M57 25v9m9-8h6M7 29h12m81 0h9M37 33h44"/>'
 ]
 wheels=[(33,73),(28,87),(25,93)]
 out='<div class="vehicle-picker" role="group" aria-label="Fahrzeugklasse für diese Leistung wählen">'
 for i,(name,shape) in enumerate(zip(['Kleinwagen','Mittelklasse','Oberklasse'],shapes)):
  wheel_markup=''.join(f'<circle class="car-tire" cx="{x}" cy="37" r="6.5"/><circle class="car-hub" cx="{x}" cy="37" r="2.5"/>' for x in wheels[i])
  icon='<svg viewBox="0 0 116 50" aria-hidden="true" focusable="false">'+shape+wheel_markup+'</svg>'
  out+=f'<button type="button" data-vehicle="{i}" aria-pressed="{str(i==0).lower()}" class="{ "selected" if i==0 else ""}">{icon}<span>{name}</span></button>'
 return out+'</div>'
def compact_offer(name,prices,tag,description,items,number,link=None):
 price=prices[0] if isinstance(prices,list) else prices
 pricing=f'<span data-prices="{",".join(map(str,prices))}">{price}</span>' if isinstance(prices,list) else str(price)
 title=html.escape(name)
 inquiry='/kontakt/?leistung='+name
 return f'<article class="offer {"offer-highlight" if name=="Gold" else ""}"><div class="offer-top"><span class="offer-number">{number:02}</span><span class="offer-tag">{tag}</span></div><div class="offer-title"><h3>{title}</h3><div class="offer-price" aria-live="polite" aria-atomic="true"><small>ab</small><strong>{pricing} €</strong><small>inkl. MwSt.*</small><span class="vehicle-caption" data-vehicle-caption>Für Kleinwagen</span></div></div><p class="offer-description">{description}</p>'+vehicle_picker()+'<details class="offer-details"><summary>Leistungen & Details</summary><ul class="checklist">'+''.join('<li>'+html.escape(x)+'</li>' for x in items)+'</ul>'+ (f'<a class="textlink" href="{link}">Mehr zur Leistung ↗</a>' if link else '')+f'<a class="btn" data-offer-inquiry href="{inquiry}&amp;klasse=Kleinwagen">Anfragen <span aria-hidden="true">↗</span></a></details></article>'
def catalog(initial='pakete'):
 groups=[('pflege','Innen & Außen','Reinigung und Aufbereitung'),('pakete','Pflegepakete','Alles passend kombiniert'),('extras','Einzeln buchbar','Schutz und Zusatzpflege')]
 out=f'<section class="section catalog" data-catalog data-initial="{initial}" id="pflege-uebersicht"><div class="wrap"><div class="heading"><div><span class="eyebrow">Leistungen & Preise</span><h2>Ihr Auto. Ihre Pflege.<br><em>Alles auf einen Blick.</em></h2></div><p>Wählen Sie einen Bereich. Der Preis steht direkt bei der Leistung – die Details öffnen Sie bei Bedarf.</p></div><div class="catalog-tabs" role="tablist" aria-label="Leistungsbereiche">'
 for i,(key,label,desc) in enumerate(groups):out+=f'<button type="button" role="tab" id="tab-{key}" aria-controls="panel-{key}" aria-selected="{str(key==initial).lower()}" data-tab="{key}"><span class="tab-number">0{i+1}</span><span><strong>{label}</strong><small>{desc}</small></span><span aria-hidden="true" class="tab-arrow">↗</span></button>'
 out+='</div><p class="catalog-class-hint">Wählen Sie Ihre Fahrzeugklasse direkt in der jeweiligen Karte.</p>'
 for key,label,_ in groups:
  out+=f'<section class="catalog-panel" id="panel-{key}" role="tabpanel" aria-labelledby="tab-{key}" data-panel="{key}"><div class="panel-intro"><h3>{label}</h3><span>{ {"pflege":"5 Leistungen","pakete":"6 Pflegepakete","extras":"18 Zusatzleistungen"}[key] }</span></div>'
  if key=='pakete':
   out+='<div class="offer-grid">'
   for i,(n,pr,desc,ls) in enumerate(all_packages):out+=compact_offer(n,pr,{'Silber':'Regelmäßige Pflege','Gold':'Intensiv gepflegt','Diamant':'Mit Keramikschutz','Platin':'Mit Nano-Schutz','Eure Berliner Autopflege':'Innen intensiv + Politur','Eure Berliner Autopflege Spezial':'Lack + Innenraum'}[n],desc,package_details[n],i+1)
   out+='</div>'
  elif key=='pflege':
   descriptions=['Schonende Handwäsche inklusive Felgen, Scheiben und Türeinstiegen.','Außenwäsche mit maschineller Politur und Kunststoffpflege außen.','Ein gepflegter Innenraum – von Cockpit und Kofferraum bis zu den Scheiben.','Mit Shampoonierung von Sitzen und Teppichen, Himmelreinigung und Kunststoffpflege.','Für die gezielte Aufbereitung matter Lackflächen und leichter Gebrauchsspuren.']
   itemlists=[['Außenwäsche von Hand','Scheiben außen, Türeinstiege und Felgenreinigung'],wash_polish,basic_inside,intensive_inside,paint+['Maschinelle Politur']]
   links=['handwaesche','handwaesche','innenreinigung','innenreinigung','lackaufbereitung']
   out+='<div class="offer-grid">'
   for i,(n,pr) in enumerate(rows[:5]):out+=compact_offer(n,pr,'Einzelleistung',descriptions[i],itemlists[i],i+1,'/leistungen/'+links[i]+'/')
   out+='</div>'
  else:
   sections=[('Versiegelung & Rückgabe',others[:4]),('Reinigung, Pflege & Reparatur',others[4:])]
   for name,entries in sections:
    out+='<div class="extras-group"><h4>'+name+'</h4><div class="extras-grid">'
    for n,pr in entries:
     link='/leistungen/keramikversiegelung/' if n=='Keramikversiegelung' else '/leistungen/leasingrueckgabe/' if n=='Leasingrückläufer-Paket' else '/kontakt/?leistung='+n
     out+=f'<a class="extra-item" href="{link}"><span class="extra-name">{n}</span><span class="extra-price"><small>ab</small> {pr}<span aria-hidden="true"> ↗</span></span></a>'
    out+='</div></div>'
   out+='<p class="fine">Für diese Zusatzleistungen sind keine unterschiedlichen Fahrzeugklassen-Preise angegeben. Umfang und Aufwand stimmen wir persönlich ab.</p>'
  out+='</section>'
 out+='<p class="fine catalog-fine">*Alle Preise inklusive 19 % MwSt. und als Ab-Preise. Der Endpreis richtet sich nach Fahrzeugtyp, Zustand und Verschmutzungsgrad und wird nach Begutachtung vereinbart.</p><div class="catalog-advice"><span>Sie sind unsicher, welche Pflege passt?</span><a href="tel:+493068918811">Wir beraten Sie: 030 68 91 88 11 ↗</a></div></div></section>'
